"""Deepgram Flux ASR engine using the ``/v2/listen`` API."""

import json
from typing import Any, Dict, List, Optional
from urllib.parse import urlencode

import structlog

from rasa.core.channels.voice_stream.asr.asr_engine import ASRLanguageMapEntry
from rasa.core.channels.voice_stream.asr.asr_event import (
    ASREvent,
    NewTranscript,
    UserIsSpeaking,
)
from rasa.core.channels.voice_stream.audio_bytes import AudioFormat

from .base import _DeepgramASRBase
from .config import DeepgramFluxASRConfig
from .constants import (
    DEEPGRAM_API_V2,
    DEFAULT_ENDPOINT,
    DEFAULT_FLUX_MODEL,
)

logger = structlog.get_logger(__name__)

DEFAULT_MODEL = DEFAULT_FLUX_MODEL


class DeepgramFluxASR(_DeepgramASRBase[DeepgramFluxASRConfig]):
    """Deepgram Flux ASR engine using turn-based transcripts."""

    api_version = DEEPGRAM_API_V2

    @classmethod
    def name(cls) -> str:
        return "deepgram_flux"

    def _get_query_params(self) -> str:
        params: Dict[str, Any] = {
            "encoding": self._encoding_for(self.audio_format),
            "sample_rate": self.audio_format.sample_rate,
            "model": self.current_language_config.model,
        }
        if self.current_language_config.engine_language_key:
            params["language_hint"] = self.current_language_config.engine_language_key
        if self.config.eot_threshold is not None:
            params["eot_threshold"] = self.config.eot_threshold
        if self.config.eot_timeout_ms is not None:
            params["eot_timeout_ms"] = self.config.eot_timeout_ms
        return urlencode(params)

    def engine_event_to_asr_event(self, event: Any) -> Optional[ASREvent]:
        """Translate a v2 websocket message into a Rasa ASR event."""
        data = event if isinstance(event, dict) else json.loads(event)
        data_type = data.get("type")

        if data_type == "Error":
            logger.error(
                "deepgram.v2.error",
                error_message=data.get("message"),
                error_code=data.get("code"),
            )
            return None

        if data_type != "TurnInfo":
            return None

        event_type = data.get("event")
        transcript = data.get("transcript", "")

        if event_type == "StartOfTurn":
            return None

        if event_type == "Update":
            if not transcript:
                return None
            return UserIsSpeaking(text=transcript)

        if event_type == "EndOfTurn":
            return NewTranscript(text=transcript)

        return None

    @staticmethod
    def get_default_config(rasa_language: str) -> DeepgramFluxASRConfig:
        """Return the default Flux configuration."""
        return DeepgramFluxASRConfig(
            endpoint=DEFAULT_ENDPOINT,
            language_map={
                rasa_language: ASRLanguageMapEntry(
                    model=DEFAULT_FLUX_MODEL,
                ),
            },
        )

    @classmethod
    def from_config_dict(
        cls,
        config: Dict[str, Any],
        format: AudioFormat,
        rasa_language: str,
        additional_languages: Optional[List[str]] = None,
    ) -> "DeepgramFluxASR":
        """Create a Flux ASR engine from a raw configuration dictionary."""
        return cls(
            rasa_language=rasa_language,
            format=format,
            config=DeepgramFluxASRConfig.model_validate(config or {}),
            additional_languages=additional_languages,
        )
